"use client";

import { useEffect, useId, useRef, useState } from "react";
import Link from "next/link";

type MenuLink = {
  label: string;
  href: string;
};

type MobileMenuProps = {
  links?: readonly MenuLink[];
};

const DEFAULT_LINKS: readonly MenuLink[] = [
  { label: "Inicio", href: "/" },
  { label: "Proyectos", href: "/proyectos" },
  { label: "Nosotros", href: "/nosotros" },
  { label: "Contacto", href: "/contacto" },
];

export function MobileMenu({
  links = DEFAULT_LINKS,
}: MobileMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const menuId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const body = document.body;
    const scrollY = window.scrollY;
    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;

    const previousStyles = {
      overflow: body.style.overflow,
      position: body.style.position,
      top: body.style.top,
      width: body.style.width,
      paddingRight: body.style.paddingRight,
    };

    // Mantiene la página visualmente en su posición mientras bloquea el scroll.
    body.style.overflow = "hidden";
    body.style.position = "fixed";
    body.style.top = `-${scrollY}px`;
    body.style.width = "100%";

    if (scrollbarWidth > 0) {
      body.style.paddingRight = `${scrollbarWidth}px`;
    }

    closeRef.current?.focus();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
        return;
      }

      if (event.key !== "Tab") return;

      const focusableElements =
        dialogRef.current?.querySelectorAll<HTMLElement>(
          [
            "a[href]",
            "button:not([disabled])",
            "[tabindex]:not([tabindex='-1'])",
          ].join(","),
        );

      if (!focusableElements?.length) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement.focus();
      } else if (
        !event.shiftKey &&
        document.activeElement === lastElement
      ) {
        event.preventDefault();
        firstElement.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);

      Object.assign(body.style, previousStyles);
      window.scrollTo(0, scrollY);
      triggerRef.current?.focus();
    };
  }, [isOpen]);

  return (
    <div className="md:hidden">
      <button
        ref={triggerRef}
        type="button"
        aria-expanded={isOpen}
        aria-controls={menuId}
        aria-label="Abrir menú de navegación"
        onClick={() => setIsOpen(true)}
        className="group inline-flex size-12 items-center justify-center rounded-full border border-black/15 bg-white text-black transition-colors hover:bg-black hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black"
      >
        <span className="sr-only">Abrir menú</span>

        <span aria-hidden="true" className="grid gap-1.5">
          <span className="block h-px w-5 bg-current transition-transform group-hover:translate-x-0.5" />
          <span className="block h-px w-3.5 bg-current transition-transform group-hover:-translate-x-0.5" />
        </span>
      </button>

      <div
        id={menuId}
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label="Menú de navegación"
        aria-hidden={!isOpen}
        className={[
          "fixed inset-0 z-[100] flex min-h-dvh flex-col overflow-y-auto",
          "bg-[#f1efea] text-[#11110f]",
          "transition-[opacity,visibility] duration-300",
          isOpen
            ? "visible opacity-100"
            : "invisible pointer-events-none opacity-0",
        ].join(" ")}
      >
        <header className="flex items-center justify-between px-6 py-5">
          <span className="text-xs font-semibold tracking-[0.22em] uppercase">
            Navegación
          </span>

          <button
            ref={closeRef}
            type="button"
            aria-label="Cerrar menú"
            onClick={() => setIsOpen(false)}
            className="group inline-flex size-12 items-center justify-center rounded-full border border-black/20 transition-colors hover:bg-black hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black"
          >
            <span aria-hidden="true" className="relative size-5">
              <span className="absolute top-1/2 left-0 h-px w-5 rotate-45 bg-current transition-transform group-hover:rotate-[135deg]" />
              <span className="absolute top-1/2 left-0 h-px w-5 -rotate-45 bg-current transition-transform group-hover:rotate-45" />
            </span>
          </button>
        </header>

        <nav
          aria-label="Navegación principal"
          className="flex flex-1 items-center px-6 py-12"
        >
          <ul className="w-full">
            {links.map((link, index) => (
              <li key={link.href} className="border-b border-black/15">
                <Link
                  href={link.href}
                  onClick={() => setIsOpen(false)}
                  className="group flex items-baseline justify-between gap-6 py-5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black"
                >
                  <span className="text-[clamp(2.75rem,14vw,6rem)] leading-none font-medium tracking-[-0.06em] transition-transform duration-300 group-hover:translate-x-3">
                    {link.label}
                  </span>

                  <span
                    aria-hidden="true"
                    className="text-xs tabular-nums opacity-45"
                  >
                    {String(index + 1).padStart(2, "0")}
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        <footer className="flex justify-between px-6 py-6 text-xs tracking-wide text-black/55">
          <span>© {new Date().getFullYear()}</span>
          <span>Menú</span>
        </footer>
      </div>
    </div>
  );
}
```

El bloqueo conserva la posición exacta de la página, compensa el ancho de la scrollbar y restaura estilos, scroll y foco al cerrar. También incluye cierre con `Escape` y focus trap accesible.
